import { Pool, PoolClient } from "pg";

const BATCH_LIMIT = 50;
const POLL_INTERVAL_MS = 1000;

interface WebhookDelivery {
  id: string;
  url: string;
  payload: unknown;
  status: "pending" | "in_flight" | "sent";
  createdAt: Date;
}

export class WebhookPoller {
  constructor(private readonly pool: Pool) {}

  /**
   * Claims the oldest pending rows and dispatches them within one transaction.
   * Runs identically on every poller replica.
   */
  async claimBatch(limit: number): Promise<WebhookDelivery[]> {
    const client: PoolClient = await this.pool.connect();
    try {
      await client.query("BEGIN");

      // Grab the oldest pending rows and lock them for this transaction.
      const { rows } = await client.query<WebhookDelivery>(
        `SELECT id, url, payload, status, created_at AS "createdAt"
         FROM webhook_deliveries
         WHERE status = 'pending'
         ORDER BY created_at
         LIMIT $1
         FOR UPDATE`,
        [limit],
      );

      for (const row of rows) {
        await this.dispatch(row);
        await client.query(
          `UPDATE webhook_deliveries SET status = 'sent' WHERE id = $1`,
          [row.id],
        );
      }

      await client.query("COMMIT");
      return rows;
    } catch (err) {
      await client.query("ROLLBACK");
      throw err;
    } finally {
      client.release();
    }
  }

  private async dispatch(row: WebhookDelivery): Promise<void> {
    await fetch(row.url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(row.payload),
    });
  }

  async runTick(): Promise<void> {
    const claimed = await this.claimBatch(BATCH_LIMIT);
    console.log(`Claimed and dispatched ${claimed.length} webhook(s)`);
  }

  start(): void {
    setInterval(() => {
      this.runTick().catch((err) => console.error("Poller tick failed", err));
    }, POLL_INTERVAL_MS);
  }
}

